#define main old_contract_main
#include "test_real_contract.c"
#undef main
static int waiting;
static lab_status flow_nav(void*u,uint64_t now,const lab_localization_view*v,const lab_live_sample*s,lab_real_command*out){if(waiting){memset(out,0,sizeof(*out));return LAB_AGAIN;}return navstep(u,now,v,s,out);}
static lab_status flow_view(void*u,lab_real_navigation_view*out){(void)u;memset(out,0,sizeof(*out));if(waiting)strcpy(out->reason,"REPLANNING");return LAB_OK;}
int main(void){contracts();fixture f;init(&f,1);events(&f,0,1);lab_real_runtime_config c;lab_real_runtime_config_default(&c);c.mode=LAB_REAL_NAVIGATION;c.allow_hardware_output=1;lab_real_bindings b={.sensors={&f,&source_ops},.localization={&f,&loc_ops},.chassis={&f,&chassis_ops},.navigation={&f,goal,cancel,flow_nav,reset,flow_view}};lab_real_runtime*r=0;CHECK(lab_real_runtime_open(&r,&c,&f.context,&b)==LAB_OK);CHECK(lab_real_runtime_tick(r,0)==LAB_AGAIN);set_goal(r,0);CHECK(lab_real_runtime_tick(r,50000)==LAB_AGAIN);CHECK(lab_real_runtime_enable(r,1,50000)==LAB_OK);CHECK(lab_real_runtime_tick(r,100000)==LAB_OK&&f.apply==1);waiting=1;CHECK(lab_real_runtime_tick(r,150000)==LAB_OK&&f.apply==2&&view(r).enabled&&view(r).has_goal&&f.stop==0&&f.arm==1);CHECK(view(r).request.linear_m_s==0&&view(r).request.expires_us>150000&&view(r).request.control_session==c.control_session);waiting=0;events(&f,200000,2);CHECK(lab_real_runtime_tick(r,200000)==LAB_OK&&f.apply==3&&f.arm==1);CHECK(lab_real_runtime_cancel(r,210000)==LAB_OK&&f.stop==1&&!view(r).enabled&&!view(r).has_goal);lab_real_runtime_close(r);free(f.events);puts("PASS ordinary wait sends zero DRIVE retaining session and target; resume does not rearm; explicit cancel stops/disarms");return 0;}
